detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of the schedule — are we minimizing the total time until all three products are completely finished (makespan), or something else like minimizing total idle time or total flow time?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting alternatives within one semantic question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all three products have to be processed in the same fixed sequence of machines (Machine 1 → Machine 2 → Machine 3), or is the machine sequence itself something we can choose as part of the schedule?"
  ],
  "rationale": "The response asks a single clarification question regarding whether the machine sequence is fixed or variable."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you say the order of the three products should remain the same on each machine, do you mean the relative order of the products must be identical across all three machines (e.g., if Product 1 is processed before Product 2 on Machine 1, it must also be before Product 2 on Machines 2 and 3), or do you mean something else?"
  ],
  "rationale": "The response asks a single clarification question regarding the interpretation of the product ordering constraint."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the three products available to start on Machine 1 at the same time (time zero), or do they have different release times?"
  ],
  "rationale": "The response asks a single clarification question regarding the release times of the products."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a product start on the next machine as soon as it finishes on the previous machine (i.e., no transfer or setup time between machines), or is there a fixed delay between consecutive machines?"
  ],
  "rationale": "The response asks for a single policy choice regarding the timing between machines, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any setup time required on a machine when switching from one product to the next, or can the next product start immediately once the previous one finishes?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of setup time between products."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many products can be in process at the same time (e.g., a maximum number of products that can be on the shop floor simultaneously), or can all three products be in process concurrently?"
  ],
  "rationale": "The response asks a single clarification question regarding the concurrency limit for products in process."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a deadline by which all three products must be completed, or is there no upper bound on the makespan?"
  ],
  "rationale": "The response asks a single clarification question regarding the makespan constraint, presenting two mutually exclusive options (deadline vs. no upper bound) for one policy decision."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Are the processing times in the table (e.g., Product 1 on Machine 1 = 2) in specific units like hours or minutes?",
    "Are they fixed constants or could they vary?"
  ],
  "rationale": "The response asks two distinct questions: one about the units of measurement and another about whether the values are fixed or variable. A user could answer the unit question without addressing the variability question, and vice versa."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a machine finishes one product and the next product in the sequence is not yet ready (still being processed on the previous machine), does the machine simply wait idle, or is there some other rule for how that idle time is handled?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy choice regarding machine idle time handling."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any constraint on the total available time for each machine (e.g., a shift length or daily capacity), or can each machine run for as long as needed?"
  ],
  "rationale": "The response asks a single clarification question regarding machine time constraints, presenting a binary choice (constrained vs. unlimited) which constitutes one independent query."
}

{
  "action": "question",
